// 正式使者批准由真实Office专项授权产生；任务不能拿普通提议或任意fact自行拼批准。
#include "diplomacy_missions.hpp"
#include "diplomacy_delegation.hpp"
#include <algorithm>
namespace hanmo::resident {
namespace {
// 记录唯一实际Grant，便于冷恢复核原授权范围；授权能力仍由原组织领域先判定。
const Grant* mission_grant(const OrganizationCatalog& catalog,const OfficeState& office,const StableId& site,Integer tick){for(const auto& id:office.grant_ids){const auto* g=catalog.grants.find(id);if(!g||g->office_id!=office.id||g->amount_limit<0||tick<g->valid_from||(g->valid_until&&tick>*g->valid_until)||std::find(g->allowed_command_kinds.begin(),g->allowed_command_kinds.end(),"diplomatic_commission_envoy")==g->allowed_command_kinds.end())continue;for(const auto& s:g->scopes)if(s.kind==ScopeRef::Kind::site&&s.id==site)return g;}return nullptr;}
template<class T>Outcome<T> failure(const StableId& code){return {false,{},common_failure(code).error};}
bool at_site(const CommonStore& c,const StableId& actor,const StableId& place){const auto* a=c.actor(actor);const auto* p=a?std::get_if<SettlementLocation>(&a->location):nullptr;return p&&p->place_id==place;}
}
// 首个批准只允许原实际签发人承担自己具名递交责任；没有以当值意愿代替他人接受。
Outcome<DiplomaticMissionApproval> preview_diplomatic_mission(const CommonStore& c,const OrganizationState& organizations,const OrganizationCatalog& oc,const DiplomacyCatalog& catalog,const DiplomacyState& state,const StableId& actor,const DiplomaticMissionCommand& cmd){
    const auto* offer=state.offers.find(cmd.offer_id);if(!offer||offer->issuer.actor_id!=actor||offer->envoy_actor_id!=actor)return failure<DiplomaticMissionApproval>("DiplomaticOfferNotKnown");
    if(offer->revision!=cmd.expected_revision||offer->last_fact_id!=cmd.source_fact_id)return failure<DiplomaticMissionApproval>("DiplomaticOfferChanged");
    if(offer->status!=DiplomaticOfferStatus::awaiting_delivery)return failure<DiplomaticMissionApproval>("DiplomaticMissionUnavailable");if(!offer->mission_authority_fact_id.empty())return failure<DiplomaticMissionApproval>("DiplomaticMissionAlreadyAuthorized");
    auto issuer=revalidate_diplomatic_issuer(c,organizations,oc,catalog,*offer);if(!issuer.ok)return {false,{},issuer.error};const auto* p=catalog.mission_policies.find(offer->policy_id);if(!p||!p->task_terms)return failure<DiplomaticMissionApproval>("DiplomaticMissionTermsMissing");const auto& t=*p->task_terms;
    if(t.acceptance_valid_ticks<=0||t.delivery_work_ticks<=0||t.continuity_policy_id!="continue_under_organization"||(t.return_report_required?t.report_work_ticks<=0:t.report_work_ticks!=0)||c.tick()>INT64_MAX-t.acceptance_valid_ticks)return failure<DiplomaticMissionApproval>("InvalidDiplomaticTaskTerms");
    if(t.return_report_required&&offer->issuer.actor_id==offer->envoy_actor_id)return failure<DiplomaticMissionApproval>("DiplomaticSelfReportUnsupported");
    if(!at_site(c,actor,p->issuer_site_id))return failure<DiplomaticMissionApproval>("DiplomaticMissionAtWrongSite");const auto* a=c.actor(actor);if(!a||!a->alive||!a->available||!a->action_id.empty())return failure<DiplomaticMissionApproval>("DiplomaticEnvoyUnavailable");
    auto proof=check_authority(c,organizations,oc,offer->issuer,"diplomatic_commission_envoy",{ScopeRef::Kind::site,p->issuer_site_id},0);if(!proof.ok)return {false,{},proof.error};const auto* office=organizations.offices.find(offer->issuer.office_id);const auto* grant=office?mission_grant(oc,*office,p->issuer_site_id,c.tick()):nullptr;if(!grant)return failure<DiplomaticMissionApproval>("DiplomaticMissionUnauthorized");
    DiplomaticMissionApproval out;out.source_identity=c.state().identity;out.proposal_id=offer->id;out.proposal_fact_id=offer->id;out.policy_id=p->id;out.rule_name_key=p->name_key;out.terms_revision=offer->terms_revision;out.issuer_organization_id=p->issuer_organization_id;out.target_organization_id=p->target_organization_id;out.envoy_actor_id=actor;out.issuer_office_id=offer->issuer.office_id;out.issuer_actor_id=actor;out.issuer_authority_epoch=offer->issuer.authority_epoch;out.issuer_grant_id=grant->id;out.target_office_id=p->target_office_id;out.delivery_site_id=p->target_site_id;out.report_office_id=offer->issuer.office_id;out.report_site_id=p->issuer_site_id;out.continuity_policy_id=t.continuity_policy_id;out.issued_tick=c.tick();out.delivery_expires_tick=offer->expires_tick;out.acceptance_expires_tick=std::min(c.tick()+t.acceptance_valid_ticks,offer->expires_tick);if(grant->valid_until&&*grant->valid_until<INT64_MAX)out.acceptance_expires_tick=std::min(out.acceptance_expires_tick,*grant->valid_until+1);out.delivery_work_ticks=t.delivery_work_ticks;out.report_work_ticks=t.report_work_ticks;out.return_report_required=t.return_report_required;if(out.delivery_expires_tick-c.tick()<=out.delivery_work_ticks)return failure<DiplomaticMissionApproval>("DiplomaticDeliveryWindowTooShort");return {true,std::move(out),{}};
}
// 签发仅产生本人已知的政治委任；不预造接受/Task/Action，也不移动钱粮或位置。
Outcome<StableId> authorize_diplomatic_mission_in_transaction(CommonStore& c,const OrganizationState& organizations,const OrganizationCatalog& oc,const DiplomacyCatalog& catalog,DiplomacyState& state,const StableId& actor,const DiplomaticMissionCommand& cmd){auto checked=preview_diplomatic_mission(c,organizations,oc,catalog,state,actor,cmd);if(!checked.ok)return {false,{},checked.error};auto id=c.next_id("diplomatic_mission");if(!id.ok)return id;auto approval=std::move(checked.value);approval.mission_authority_fact_id=id.value;approval.source_identity={};auto recorded=c.append_fact({id.value,diplomatic_mission_authority_fact_kind,diplomatic_fact_domain});if(!recorded.ok)return {false,{},recorded.error};if(!state.missions.insert(id.value,std::move(approval)))return failure<StableId>("DuplicateDiplomaticMission");state.offers.find(cmd.offer_id)->mission_authority_fact_id=id.value;return id;}
// 内部历史口核真实公共头与原提议绑定；source_identity每次只标当前读取候选，不持久化。
Outcome<DiplomaticMissionApproval> DiplomaticMissionAccess::diplomatic_mission_source(const StableId& id)const{const auto* m=state_.missions.find(id);const auto* h=common_.state().facts.find(id);const auto* o=m?state_.offers.find(m->proposal_id):nullptr;if(!m||!h||h->kind!=diplomatic_mission_authority_fact_kind||h->domain!=diplomatic_fact_domain||m->mission_authority_fact_id!=id||!o||o->mission_authority_fact_id!=id||m->proposal_fact_id!=o->id||m->terms_revision!=o->terms_revision||m->issued_tick>common_.tick())return failure<DiplomaticMissionApproval>("InvalidDiplomaticMissionSource");auto out=*m;out.source_identity=common_.state().identity;return {true,std::move(out),{}};}
// 先核本人实际指定和已签发来源，再透露当前失权/期限或对方情况。
Outcome<DiplomaticMissionApproval> DiplomaticMissionAccess::diplomatic_mission_for_acceptance(const StableId& id,const StableId& actor)const{const auto* m=state_.missions.find(id);if(!m||m->envoy_actor_id!=actor)return failure<DiplomaticMissionApproval>("DiplomaticMissionNotKnown");if(m->issuer_actor_id!=actor){if(catalog_.version!=2||state_.version!=2||!catalog_.v2||!state_.v2)return failure<DiplomaticMissionApproval>("DiplomaticMissionNotKnown");DiplomaticDelegatedMissionAccess delegated(DiplomaticHistoryRead{common_,organizations_,organization_catalog_,catalog_,state_},*catalog_.v2,*state_.v2);return delegated.diplomatic_mission_for_acceptance(id,actor);}auto source=diplomatic_mission_source(id);if(!source.ok)return source;if(common_.tick()>=m->acceptance_expires_tick)return failure<DiplomaticMissionApproval>("DiplomaticMissionAcceptanceExpired");const auto* offer=state_.offers.find(m->proposal_id);if(offer->status!=DiplomaticOfferStatus::awaiting_delivery)return failure<DiplomaticMissionApproval>("DiplomaticMissionUnavailable");auto valid=revalidate_diplomatic_issuer(common_,organizations_,organization_catalog_,catalog_,*offer);if(!valid.ok)return {false,{},valid.error};ActingAuthority authority{m->issuer_organization_id,m->issuer_office_id,m->issuer_authority_epoch,m->issuer_actor_id};auto authorized=check_authority(common_,organizations_,organization_catalog_,authority,"diplomatic_commission_envoy",{ScopeRef::Kind::site,m->report_site_id},0);if(!authorized.ok)return {false,{},authorized.error};if(!at_site(common_,actor,m->report_site_id))return failure<DiplomaticMissionApproval>("DiplomaticMissionAtWrongSite");if(m->delivery_expires_tick-common_.tick()<=m->delivery_work_ticks)return failure<DiplomaticMissionApproval>("DiplomaticDeliveryWindowTooShort");return source;}
// 接受后的正常权限变化进入待改派，死亡或组织解散才归明确终止原因；不生成假的原因fact。
Outcome<DiplomaticMissionContinuity> DiplomaticMissionAccess::diplomatic_mission_continuity(const StableId& id,const StableId& actor)const{auto source=diplomatic_mission_source(id);if(!source.ok)return {false,{},source.error};const auto& m=source.value;if(m.envoy_actor_id!=actor)return failure<DiplomaticMissionContinuity>("DiplomaticMissionNotKnown");const auto* a=common_.actor(actor);const auto* org=organizations_.organizations.find(m.issuer_organization_id);using K=DiplomaticMissionContinuityKind;const auto result=[](K k,const StableId& code)->Outcome<DiplomaticMissionContinuity>{return {true,{k,code,{}},{}};};if(!a||!org)return failure<DiplomaticMissionContinuity>("InvalidDiplomaticMissionResponsibilitySource");if(!a->alive)return result(K::terminate_envoy_dead,"DiplomaticEnvoyDead");if(org->status==OrganizationStatus::dissolved)return result(K::terminate_principal_dissolved,"DiplomaticPrincipalDissolved");if(!a->available)return result(K::pause_envoy,"DiplomaticEnvoyUnavailable");ActingAuthority authority{m.issuer_organization_id,m.issuer_office_id,m.issuer_authority_epoch,m.issuer_actor_id};auto valid=check_authority(common_,organizations_,organization_catalog_,authority,"diplomatic_commission_envoy",{ScopeRef::Kind::site,m.report_site_id},0);if(!valid.ok)return result(K::needs_reassignment,valid.error.original.code);return result(K::continue_work,{});}
// 交接报价核当前真实使者、原批准、条款、目标Office/Grant与此刻接触；不读取签发人的远方位置。
Status preview_diplomatic_mission_contact(const DiplomaticPresentRead& c,const StableId& authority_fact_id,const StableId& envoy,const FaceToFaceContactProof& contact){
    const auto* m=c.state.missions.find(authority_fact_id);if(!m||m->envoy_actor_id!=envoy)return common_failure("DiplomaticMissionNotKnown");DiplomaticMissionAccess access(c.common,c.organizations,c.organization_catalog,c.catalog,c.state);auto original=access.diplomatic_mission_source(authority_fact_id);if(!original.ok)return {false,{},original.error};auto continuity=access.diplomatic_mission_continuity(authority_fact_id,envoy);if(!continuity.ok)return {false,{},continuity.error};if(continuity.value.kind!=DiplomaticMissionContinuityKind::continue_work)return common_failure(continuity.value.code);const auto* offer=c.state.offers.find(m->proposal_id);if(!offer||offer->status!=DiplomaticOfferStatus::awaiting_delivery||offer->terms_revision!=m->terms_revision)return common_failure("DiplomaticOfferChanged");if(c.common.tick()>=m->delivery_expires_tick)return common_failure("DiplomaticOfferExpired");auto issuer=revalidate_diplomatic_issuer(c.common,c.organizations,c.organization_catalog,c.catalog,*offer);if(!issuer.ok)return issuer;const auto* office=c.organizations.offices.find(m->target_office_id);if(!office||office->organization_id!=m->target_organization_id||!office->holder_actor_id)return common_failure("DiplomaticRepresentativeUnavailable");if(contact.actor_id!=envoy||contact.target_actor_id!=*office->holder_actor_id||contact.context.place_id!=m->delivery_site_id)return common_failure("DiplomaticContactChanged");ActingAuthority representative{office->organization_id,office->id,office->epoch,*office->holder_actor_id};auto authority=check_authority(c.common,c.organizations,c.organization_catalog,representative,"diplomatic_receive_passage",{ScopeRef::Kind::site,m->delivery_site_id},0);if(!authority.ok)return common_failure("DiplomaticRepresentativeUnauthorized");return revalidate_face_to_face_contact(c.common,c.interaction,c.interaction_catalog,c.interaction_access,contact);
}
// 首个亲递记录没有Task绑定，因而不能被任务冷恢复冒用为某次交接履约。
Outcome<DiplomaticPresentationSource> DiplomaticMissionAccess::diplomatic_presentation_source(const StableId& id)const{Integer through=common_.tick();if(phase_){const auto& now=common_.state().identity;if(phase_->from_tick==INT64_MAX||phase_->to_tick!=phase_->from_tick+1||phase_identity_.tick!=phase_->from_tick||now.world_id!=phase_identity_.world_id||now.execution_epoch!=phase_identity_.execution_epoch||now.revision!=phase_identity_.revision||(now.tick!=phase_->from_tick&&now.tick!=phase_->to_tick))return failure<DiplomaticPresentationSource>("InvalidDiplomaticPhaseRead");through=phase_->to_tick;}const auto* p=state_.presentations.find(id);const auto* h=common_.state().facts.find(id);const auto* o=p?state_.offers.find(p->offer_id):nullptr;if(!p||!h||h->domain!=diplomatic_fact_domain||h->kind!=diplomatic_presentation_fact_kind||p->id!=id||!o||p->proposal_fact_id!=o->id||p->terms_revision!=o->terms_revision||p->tick>through)return failure<DiplomaticPresentationSource>("InvalidDiplomaticPresentationSource");return {true,{p->id,p->offer_id,p->proposal_fact_id,p->envoy_actor_id,p->terms_revision,p->tick,p->task_binding},{}};}
}
